CREATE TABLE public.game_comments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,game_name text NOT NULL,message text NOT NULL CHECK(char_length(message) BETWEEN 5 AND 1000),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),hidden boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.game_comments TO authenticated;
GRANT SELECT ON public.game_comments TO anon;
GRANT ALL ON public.game_comments TO service_role;
ALTER TABLE public.game_comments ENABLE ROW LEVEL SECURITY;
CREATE POLICY comments_public ON public.game_comments FOR SELECT TO anon,authenticated USING(NOT hidden);
CREATE POLICY comments_own_read ON public.game_comments FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY comments_own_insert ON public.game_comments FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND NOT hidden);
CREATE POLICY comments_own_update ON public.game_comments FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY comments_own_delete ON public.game_comments FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.comment_likes(comment_id uuid NOT NULL REFERENCES public.game_comments(id) ON DELETE CASCADE,user_id uuid NOT NULL,PRIMARY KEY(comment_id,user_id));
GRANT SELECT,INSERT,DELETE ON public.comment_likes TO authenticated;
GRANT ALL ON public.comment_likes TO service_role;
ALTER TABLE public.comment_likes ENABLE ROW LEVEL SECURITY;
CREATE POLICY likes_own_read ON public.comment_likes FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY likes_own_insert ON public.comment_likes FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND EXISTS(SELECT 1 FROM game_comments WHERE id=comment_id AND NOT hidden AND user_id<>auth.uid()));
CREATE POLICY likes_own_delete ON public.comment_likes FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.xp_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,event_key text NOT NULL,points integer NOT NULL CHECK(points BETWEEN 1 AND 100),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,event_key));
GRANT SELECT ON public.xp_events TO authenticated;
GRANT ALL ON public.xp_events TO service_role;
ALTER TABLE public.xp_events ENABLE ROW LEVEL SECURITY;
CREATE POLICY xp_own ON public.xp_events FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.award_social_xp() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; p integer; BEGIN PERFORM pg_advisory_xact_lock(hashtext(NEW.user_id::text)); IF TG_TABLE_NAME='game_ratings' THEN k='rating:'||NEW.game_name; p=5; ELSIF TG_TABLE_NAME='request_votes' THEN k='vote:'||NEW.request_id::text;p=2; ELSE RETURN NEW; END IF; IF (SELECT coalesce(sum(points),0) FROM xp_events WHERE user_id=NEW.user_id AND created_at::date=current_date)+p<=50 THEN INSERT INTO xp_events(user_id,event_key,points) VALUES(NEW.user_id,k,p) ON CONFLICT DO NOTHING; END IF; RETURN NEW; END $$;
CREATE TRIGGER rating_xp AFTER INSERT ON public.game_ratings FOR EACH ROW EXECUTE FUNCTION public.award_social_xp();
CREATE TRIGGER vote_xp AFTER INSERT ON public.request_votes FOR EACH ROW EXECUTE FUNCTION public.award_social_xp();
CREATE OR REPLACE FUNCTION public.validate_comment_write() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM consume_action_budget('comment',10,3600); IF TG_OP='INSERT' THEN NEW.created_at=now();NEW.hidden=false; ELSE NEW.created_at=OLD.created_at;NEW.user_id=OLD.user_id;NEW.game_name=OLD.game_name; IF NEW.hidden<>OLD.hidden AND NOT admin_is_unlocked() THEN RAISE EXCEPTION 'Acesso negado'; END IF; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER comment_write BEFORE INSERT OR UPDATE ON public.game_comments FOR EACH ROW EXECUTE FUNCTION public.validate_comment_write();
CREATE TRIGGER like_budget BEFORE INSERT OR DELETE ON public.comment_likes FOR EACH ROW EXECUTE FUNCTION public.limit_social_write();
CREATE OR REPLACE FUNCTION public.comment_page(_game text,_sort text DEFAULT 'recent',_offset integer DEFAULT 0) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(t),'[]'::jsonb) FROM (SELECT c.id,c.message,c.created_at,c.updated_at,p.display_name,(c.user_id=auth.uid()) AS is_mine,(SELECT count(*) FROM comment_likes l WHERE l.comment_id=c.id) likes,EXISTS(SELECT 1 FROM comment_likes l WHERE l.comment_id=c.id AND l.user_id=auth.uid()) liked FROM game_comments c JOIN profiles p ON p.id=c.user_id WHERE c.game_name=_game AND NOT c.hidden ORDER BY CASE WHEN _sort='likes' THEN (SELECT count(*) FROM comment_likes l WHERE l.comment_id=c.id) ELSE 0 END DESC,c.created_at DESC,c.id LIMIT 20 OFFSET greatest(0,least(_offset,10000)))t $$;
REVOKE ALL ON FUNCTION public.comment_page(text,text,integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.comment_page(text,text,integer) TO anon,authenticated;
CREATE INDEX comments_game_date ON public.game_comments(game_name,created_at DESC);
CREATE INDEX xp_user_date ON public.xp_events(user_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.validate_request_unique() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE key text; BEGIN key=regexp_replace(lower(trim(NEW.title)),'[^[:alnum:]]','','g'); PERFORM pg_advisory_xact_lock(hashtext('request:'||key)); IF EXISTS(SELECT 1 FROM game_requests WHERE id<>NEW.id AND regexp_replace(lower(trim(title)),'[^[:alnum:]]','','g')=key AND status IN ('open','review','resolved')) THEN RAISE EXCEPTION 'Já existe um pedido desse jogo. Vote no pedido existente.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER request_unique BEFORE INSERT OR UPDATE OF title ON public.game_requests FOR EACH ROW EXECUTE FUNCTION public.validate_request_unique();
CREATE OR REPLACE FUNCTION public.player_progress() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT jsonb_build_object('xp',coalesce((SELECT sum(points) FROM xp_events WHERE user_id=auth.uid()),0),'ratings',(SELECT count(*) FROM game_ratings WHERE user_id=auth.uid()),'comments',(SELECT count(*) FROM game_comments WHERE user_id=auth.uid()),'games',(SELECT count(*) FROM player_library WHERE user_id=auth.uid() AND played_at IS NOT NULL),'activity',coalesce((SELECT jsonb_agg(t) FROM (SELECT event_key,points,created_at FROM xp_events WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 30)t),'[]'::jsonb)) $$;
REVOKE ALL ON FUNCTION public.player_progress() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.player_progress() TO authenticated;